<?php require_once __DIR__.'/../includes/bootstrap.php';require_role('Parent/Guardian');$q=db()->prepare('SELECT s.id,u.name,s.enrollment_no,s.department_id FROM parent_students ps JOIN parents p ON p.id=ps.parent_id JOIN students s ON s.id=ps.student_id JOIN users u ON u.id=s.user_id WHERE p.user_id=?');$q->execute([actor_id()]);$kids=$q->fetchAll();page_top('Parent / Guardian Portal');?><div class='row g-4'><?php foreach($kids as $k):$a=db()->prepare('SELECT ROUND(100*SUM(status="Present")/NULLIF(COUNT(*),0),1) FROM attendance WHERE student_id=?');$a->execute([$k['id']]);$att=$a->fetchColumn();$f=db()->prepare('SELECT COALESCE(SUM(amount-discount-paid_amount),0) FROM student_fees WHERE student_id=?');$f->execute([$k['id']]);$fee=$f->fetchColumn();$m=db()->prepare('SELECT COUNT(*) FROM marks WHERE student_id=?');$m->execute([$k['id']]);$marks=$m->fetchColumn();?><div class='col-md-6 col-xl-4'><div class='card p-4'><span class='pill'>LINKED STUDENT</span><h4 class='mt-2'><?=e($k['name'])?></h4><div class='text-muted'><?=e($k['enrollment_no'])?></div><hr><div class='row g-2'><div class='col-4'><small>Attendance</small><strong class='d-block'><?=e($att??'—')?>%</strong></div><div class='col-4'><small>Fee Due</small><strong class='d-block'>₹<?=e(number_format((float)$fee,0))?></strong></div><div class='col-4'><small>Marks</small><strong class='d-block'><?=e($marks)?></strong></div></div></div></div><?php endforeach;?></div><?php page_bottom();
